const NS='http://www.w3.org/2000/svg';
const palette=['#0b6b4b','#d69e36','#3f6d88','#a85350','#778d68','#7b5ea7','#c56f2f'];
let seed=20260907;
const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const el=(tag,attrs={})=>{const n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n};
function svgFor(id,label){const host=document.getElementById(id);host.innerHTML='';const svg=el('svg',{viewBox:'0 0 440 230',role:'img','aria-label':label});host.append(svg);return svg}
function axes(svg,xLabels=['0','50','100'],yLabels=['0','50','100']){[0,1,2].forEach(i=>{const y=190-i*80;svg.append(el('line',{x1:42,y1:y,x2:425,y2:y,class:'grid'}));const t=el('text',{x:34,y:y+3,'text-anchor':'end'});t.textContent=yLabels[i];svg.append(t)});xLabels.forEach((v,i)=>{const t=el('text',{x:42+i*191.5,y:212,'text-anchor':i===0?'start':i===2?'end':'middle'});t.textContent=v;svg.append(t)});svg.append(el('line',{x1:42,y1:30,x2:42,y2:190,class:'axis'}));svg.append(el('line',{x1:42,y1:190,x2:425,y2:190,class:'axis'}))}
function pathLine(svg,data,cls='primary',min=0,max=Math.max(...data.filter(Number.isFinite))){const pts=data.map((v,i)=>Number.isFinite(v)?`${42+i*383/(data.length-1)},${190-(v-min)/(max-min||1)*150}`:null).filter(Boolean).join(' ');svg.append(el('polyline',{points:pts,class:cls,'stroke-linecap':'round','stroke-linejoin':'round'}));return pts}
function lineChart(id,series,label,opts={}){const svg=svgFor(id,label);axes(svg,opts.x||['inicio','mitad','fin'],opts.y||['0','','máx']);const all=series.flatMap(s=>s.data);const min=opts.min??Math.min(0,...all),max=opts.max??Math.max(...all)*1.08;series.forEach((s,i)=>pathLine(svg,s.data,s.className||(['primary','secondary'][i]||'primary'),min,max));}
function barChart(id,data,labels,label,opts={}){const svg=svgFor(id,label);axes(svg,[labels[0],labels[Math.floor(labels.length/2)],labels.at(-1)],opts.y||['0','','máx']);const max=opts.max||Math.max(...data)*1.1;const w=340/data.length;data.forEach((v,i)=>{const h=v/max*150;svg.append(el('rect',{x:55+i*w,y:190-h,width:Math.max(4,w-5),height:h,class:`bar ${i%2?'':'alt'}`,rx:2}))})}
function areaChart(id,data,label){const svg=svgFor(id,label);axes(svg);const pts=data.map((v,i)=>`${42+i*383/(data.length-1)},${190-v/Math.max(...data)*145}`);svg.append(el('polygon',{points:`42,190 ${pts.join(' ')} 425,190`,class:'fill-primary'}));svg.append(el('polyline',{points:pts.join(' '),class:'primary'}))}
function heatmap(id,rows,cols,label){const svg=svgFor(id,label),x0=55,y0=35,w=350/cols,h=145/rows;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const v=(Math.sin(r*1.6+c*.7)+1)/2;svg.append(el('rect',{x:x0+c*w,y:y0+r*h,width:w-2,height:h-2,fill:`rgba(11,107,75,${.12+.75*v})`,rx:2}));}['1','7','14','21','30'].forEach((v,i)=>{const t=el('text',{x:x0+i*350/4,y:205,'text-anchor':'middle'});t.textContent=v;svg.append(t)})}
function confusion(id,tp,fp,fn,tn){const svg=svgFor(id,'Matriz de confusión con verdaderos y falsos positivos');const vals=[[tn,fp],[fn,tp]],labs=[['TN','FP'],['FN','TP']],max=Math.max(tp,fp,fn,tn);vals.forEach((row,r)=>row.forEach((v,c)=>{svg.append(el('rect',{x:85+c*140,y:35+r*85,width:132,height:77,fill:`rgba(11,107,75,${.15+.8*v/max})`,rx:4}));let t=el('text',{x:151+c*140,y:68+r*85,'text-anchor':'middle',style:'font-size:11px;fill:currentColor'});t.textContent=labs[r][c];svg.append(t);t=el('text',{x:151+c*140,y:92+r*85,'text-anchor':'middle',style:'font-size:22px;font-weight:800;fill:currentColor'});t.textContent=v;svg.append(t)}));}
function scatter(id,points,k,label){const svg=svgFor(id,label);axes(svg,['S/ 280k','ticket','S/ 780k'],['baja','','alta']);points.forEach((p,i)=>svg.append(el('circle',{cx:48+p.x*370,cy:185-p.y*145,r:3.5,fill:palette[i%k],opacity:.75})));}
function radar(id,k,label){const svg=svgFor(id,label),cx=220,cy=115,R=78,n=5;for(let r=1;r<=4;r++){const pts=Array.from({length:n},(_,i)=>`${cx+R*r/4*Math.cos(-Math.PI/2+i*2*Math.PI/n)},${cy+R*r/4*Math.sin(-Math.PI/2+i*2*Math.PI/n)}`).join(' ');svg.append(el('polygon',{points:pts,fill:'none',stroke:'var(--line)'}))}for(let g=0;g<k;g++){const vals=Array.from({length:n},(_,i)=>.2+.72*((Math.sin((g+1)*(i+2))+1)/2));const pts=vals.map((v,i)=>`${cx+R*v*Math.cos(-Math.PI/2+i*2*Math.PI/n)},${cy+R*v*Math.sin(-Math.PI/2+i*2*Math.PI/n)}`).join(' ');svg.append(el('polygon',{points:pts,fill:palette[g]+'22',stroke:palette[g],'stroke-width':2}))}}
function setInsights(id,items){const host=document.getElementById(id);host.replaceChildren();const head=document.createElement('header');const title=document.createElement('span');title.textContent='SMART INSIGHTS';const note=document.createElement('small');note.textContent='Lectura automática del escenario';head.append(title,note);host.append(head);items.forEach(item=>{const card=document.createElement('article');const label=document.createElement('span');const headline=document.createElement('strong');const detail=document.createElement('p');label.textContent=item.label;headline.textContent=item.headline;detail.textContent=item.detail;card.append(label,headline,detail);host.append(card)})}
function renderForecast(){seed=20260907+Number(document.querySelector('[data-rerun="forecast"]').dataset.n||0);const h=+horizon.value,s=+season.value/10,n=+noise.value/10;horizonOut.value=h+' días';seasonOut.value=s.toFixed(1)+'×';noiseOut.value=n<.5?'bajo':n<1.3?'medio':'alto';const actual=Array.from({length:30},(_,i)=>clamp(1.2+.045*i+s*.75*Math.sin(i*Math.PI/3.5)+(rand()-.5)*n,0,5));const fc=Array.from({length:h},(_,i)=>clamp(2.4+.045*i+s*.7*Math.sin((i+30)*Math.PI/3.5),0,5));lineChart('forecast-main',[{data:actual},{data:[...Array(29).fill(NaN),actual.at(-1),...fc],className:'secondary'}],'Curva de ventas diarias observadas y pronosticadas',{x:['día 1','día 30','forecast'],y:['0','2.5','5']});const base=Array.from({length:h},(_,i)=>1.4+i*.07);lineChart('forecast-interval',[{data:base.map((v,i)=>v+.35+.025*i),className:'secondary'},{data:base},{data:base.map((v,i)=>v-.35-.025*i),className:'secondary'}],'Intervalos de predicción que se abren con el horizonte');barChart('forecast-residual',actual.slice(-18).map((v,i)=>Math.abs(v-(1.2+.045*(i+12)))*10),Array.from({length:18},(_,i)=>i+1),'Magnitud de residuos por día');barChart('forecast-acf',Array.from({length:12},(_,i)=>Math.max(0,8-i*.65)+Math.sin(i*1.8)*1.5),Array.from({length:12},(_,i)=>i+1),'Autocorrelación por rezago');heatmap('forecast-error',4,8,'Mapa de error absoluto por horizonte y escenario');const total=Math.round(fc.reduce((a,b)=>a+b,0)),recent=actual.slice(-7).reduce((a,b)=>a+b,0)/7,future=fc.reduce((a,b)=>a+b,0)/h,delta=Math.round((future/recent-1)*100),uncertainty=Math.round(8+n*6);forecastDecision.textContent=`Escenario: ${total} separaciones esperadas · ±${uncertainty}%`;setInsights('forecastInsights',[{label:'LECTURA ACTUAL',headline:`La velocidad proyectada ${delta>=0?'sube':'baja'} ${Math.abs(delta)}%`,detail:`El escenario acumula ${total} separaciones en ${h} días y mantiene una incertidumbre aproximada de ±${uncertainty}%.`},{label:'QUÉ HACE EL MODELO',headline:'Extiende patrones; no conoce el futuro',detail:'El modelo combina tendencia y estacionalidad observadas. Eventos nuevos, cambios de pauta o stock requieren variables adicionales.'},{label:'CRITERIO DE DECISIÓN',headline:uncertainty>17?'Conviene planificar un rango de capacidad':'La señal permite una meta operativa más estrecha',detail:uncertainty>17?'La amplitud del intervalo desaconseja tratar el punto medio como compromiso único.':'La menor dispersión permite convertir el escenario central en referencia, manteniendo un margen de seguridad.'}])}
function renderChurn(){const t=+threshold.value/100,d=+depth.value,e=+eta.value/100;thresholdOut.value=t.toFixed(2);depthOut.value=d;etaOut.value=e.toFixed(2);const positives=34,negatives=66,tpr=clamp(1.08-t*.82,0,1),fpr=clamp(.7-t*.82,0,1),tp=Math.round(positives*tpr),fn=positives-tp,fp=Math.round(negatives*fpr),tn=negatives-fp;const roc=Array.from({length:20},(_,i)=>Math.pow(i/19,.35+.03*(8-d)));lineChart('churn-roc',[{data:roc},{data:Array.from({length:20},(_,i)=>i/19),className:'ref'}],'Curva ROC frente a clasificador aleatorio',{max:1,min:0,x:['0 FPR','','1'],y:['0 TPR','','1']});lineChart('churn-calibration',[{data:[.05,.14,.22,.31,.44,.52,.68,.77,.86,.92]},{data:[.05,.15,.25,.35,.45,.55,.65,.75,.85,.95],className:'ref'}],'Curva de calibración frente a diagonal ideal',{max:1,min:0});confusion('churn-confusion',tp,fp,fn,tn);barChart('churn-features',[8.8,7.2,6.5,4.9,3.8],['días','cuota','contactos','banco','asesor'],'Importancia relativa de variables');const profits=Array.from({length:13},(_,i)=>80-((i/12-.55)**2)*190+d*1.2-e*8);lineChart('churn-profit',[{data:profits}],'Beneficio esperado según umbral',{x:['0.2','umbral','0.8'],y:['bajo','','alto']});const flagged=tp+fp,precision=Math.round(tp/(flagged||1)*100),recall=Math.round(tp/positives*100);churnDecision.textContent=`Atender ${flagged} casos; ${tp} caídas detectadas · precisión ${precision}%`;setInsights('churnInsights',[{label:'LECTURA ACTUAL',headline:`El modelo prioriza ${flagged} de cada 100 casos`,detail:`La regla detecta ${recall}% de las caídas y alcanza ${precision}% de precisión con el umbral ${t.toFixed(2)}.`},{label:'QUÉ HACE EL MODELO',headline:'Ordena riesgo; no demuestra causalidad',detail:'XGBoost combina reglas de múltiples árboles. Una variable importante ayuda a predecir, pero no necesariamente causa la caída.'},{label:'CRITERIO DE DECISIÓN',headline:t<.4?'La cobertura aumenta a costa de más falsas alarmas':t>.65?'La carga baja, pero se omiten más caídas':'El umbral mantiene un balance operativo',detail:d>6?'La profundidad elevada también exige revisar sobreajuste fuera de muestra.':'El valor final debe compararse con el costo de contactar y el costo de perder una venta.'}])}
function renderCluster(){const kVal=+k.value,scale=+incomeScale.value/10,ini=+inits.value;kOut.value=kVal;incomeOut.value=scale.toFixed(1)+'×';initOut.value=ini;seed=881+kVal+ini;const centers=Array.from({length:kVal},(_,i)=>({x:.15+.7*((i*2%kVal)/(Math.max(1,kVal-1))),y:.15+.7*((i*3%kVal)/(Math.max(1,kVal-1)))}));const pts=Array.from({length:110},(_,i)=>{const c=i%kVal;return{x:clamp(centers[c].x+(rand()-.5)*.22/scale,0,1),y:clamp(centers[c].y+(rand()-.5)*.25,0,1)}});scatter('cluster-scatter',pts,kVal,'Clientes sintéticos agrupados por ticket y urgencia');const inertia=Array.from({length:7},(_,i)=>95/Math.pow(i+1,.72)+5);lineChart('cluster-elbow',[{data:inertia}],'Inercia decreciente al aumentar clusters',{x:['k=1','k=4','k=7'],y:['baja','','alta']});const sil=Array.from({length:kVal},(_,i)=>35+25*Math.sin((i+1)*1.3)**2);barChart('cluster-silhouette',sil,Array.from({length:kVal},(_,i)=>'C'+(i+1)),'Silueta media por cluster',{max:100});radar('cluster-profile',kVal,'Perfil radial de ingreso, urgencia, dormitorios, canal y engagement');const conv=Array.from({length:kVal},(_,i)=>20+55*((Math.sin(i*1.8)+1)/2));barChart('cluster-value',conv,Array.from({length:kVal},(_,i)=>'C'+(i+1)),'Conversión de cada segmento',{max:100,y:['0%','50%','100%']});const silhouette=0.42+ini*.006-kVal*.008,best=conv.indexOf(Math.max(...conv))+1;clusterDecision.textContent=`${kVal} segmentos; silueta media ${silhouette.toFixed(2)}`;setInsights('clusterInsights',[{label:'LECTURA ACTUAL',headline:`El segmento C${best} muestra la mayor conversión`,detail:`La partición genera ${kVal} grupos con silueta ${silhouette.toFixed(2)}; ${silhouette>=.5?'la separación es razonable':'varios casos permanecen cerca de las fronteras'}.`},{label:'QUÉ HACE EL MODELO',headline:'Agrupa cercanía; no descubre personas naturales',detail:'K-means minimiza distancias respecto de centroides. Los nombres y el significado comercial se asignan después del cálculo.'},{label:'CRITERIO DE DECISIÓN',headline:kVal>5?'La complejidad puede superar la capacidad comercial':'La segmentación conserva una escala operable',detail:ini<5?'Pocas inicializaciones reducen la confianza en la estabilidad de los grupos.':'La utilidad debe validarse con campañas, estabilidad temporal y conversión fuera de muestra.'}])}
function renderBandit(){const eps=+epsilon.value/100,day=+days.value,disc=+discount.value;epsilonOut.value=Math.round(eps*100)+'%';daysOut.value=day;discountOut.value=disc+'%';const prices=[100,98,96,94,92].slice(0,Math.max(3,Math.ceil(disc/3)));const demand=prices.map(p=>16+Math.pow(100-p,1.35)*1.8);lineChart('bandit-demand',[{data:demand}],'Demanda estimada según índice de precio',{x:['precio alto','','descuento'],y:['baja','','alta']});const reward=prices.map((p,i)=>p*demand[i]/20);barChart('bandit-reward',reward,prices.map(p=>p+'%'),'Recompensa esperada por precio');const regret=Array.from({length:20},(_,i)=>Math.sqrt(i+1)*(1.3+eps*7));areaChart('bandit-regret',regret,'Regret acumulado durante el aprendizaje');const shares=prices.map((_,i)=>Math.max(5,55-i*12+eps*100*(i?1:-1)));barChart('bandit-share',shares,prices.map(p=>p+'%'),'Participación de acciones elegidas');seed=400+day+disc;const outcomes=Array.from({length:16},()=>45+rand()*40+eps*12);barChart('bandit-outcome',outcomes,Array.from({length:16},(_,i)=>i+1),'Ingresos diarios sintéticos');const best=reward.indexOf(Math.max(...reward)),expected=(1.62+disc*.025-eps*.1).toFixed(2),finalRegret=regret.at(-1).toFixed(1);banditDecision.textContent=`Explorar ${Math.round(eps*100)}%; ingreso esperado S/ ${expected}M · guardrail margen activo`;setInsights('banditInsights',[{label:'LECTURA ACTUAL',headline:`La acción líder conserva ${prices[best]}% del precio`,detail:`La política proyecta S/ ${expected}M y acumula ${finalRegret} puntos de regret en ${day} días simulados.`},{label:'QUÉ HACE EL MODELO',headline:'Aprende con feedback parcial',detail:'El bandit observa la recompensa de la acción elegida, no de todas las alternativas. Por ello conserva exploración controlada.'},{label:'CRITERIO DE DECISIÓN',headline:eps>0.25?'La exploración es alta para una operación estable':eps<0.05?'La política aprende muy poco de alternativas':'La exploración mantiene un balance prudente',detail:disc>10?'El descuento máximo también requiere un guardrail explícito de margen.':'La política solo debe operar dentro de límites de precio, margen y elegibilidad previamente aprobados.'}])}
const renders={forecast:renderForecast,churn:renderChurn,cluster:renderCluster,bandit:renderBandit};
document.querySelectorAll('.lab-tab').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.lab-tab').forEach(x=>{x.classList.toggle('active',x===btn);x.setAttribute('aria-selected',String(x===btn))});document.querySelectorAll('.lab-panel').forEach(x=>x.classList.toggle('active',x.dataset.labPanel===btn.dataset.lab));renders[btn.dataset.lab]()}));
document.querySelectorAll('input[type=range]').forEach(i=>i.addEventListener('input',()=>renders[i.closest('.lab-panel').dataset.labPanel]()));
document.querySelectorAll('.rerun').forEach(b=>b.addEventListener('click',()=>{b.dataset.n=String((+b.dataset.n||0)+1);renders[b.dataset.rerun]()}));
